import numpy as np
from collections import Counter

def gol_step(grid):
    new_grid = grid.copy()
    rows, cols = grid.shape
    for i in range(rows):
        for j in range(cols):
            live_neighbors = 0
            for x in range(-1, 2):
                for y in range(-1, 2):
                    if (x != 0 or y != 0) and (0 <= i + x < rows) and (0 <= j + y < cols):
                        live_neighbors += grid[i + x, j + y]
            if grid[i, j] == 1 and (live_neighbors < 2 or live_neighbors > 3):
                new_grid[i, j] = 0
            elif grid[i, j] == 0 and live_neighbors == 3:
                new_grid[i, j] = 1
    return new_grid

def shannon_entropy(grid, block_size=2):
    rows, cols = grid.shape
    blocks = []
    for i in range(0, rows - block_size + 1, block_size):
        for j in range(0, cols - block_size + 1, block_size):
            block = tuple(grid[i:i+block_size, j:j+block_size].flatten())
            blocks.append(block)
    counts = Counter(blocks)
    total = sum(counts.values())
    probs = np.array([c / total for c in counts.values()])
    return -np.sum(probs * np.log2(probs + 1e-12))

def lempel_ziv_complexity(binary_sequence):
    n = len(binary_sequence)
    if n == 0: return 0
    complexity = 1
    i = 1
    while i < n:
        j = 1
        found = True
        while i + j <= n:
            substring = binary_sequence[i:i+j]
            prefix = binary_sequence[0:i+j-1]
            if substring not in prefix:
                complexity += 1
                i += j
                found = False
                break
            j += 1
        if found: break
    return complexity

def get_block_config(size=(20, 20)):
    grid = np.zeros(size, dtype=int)
    grid[size[0]//2:size[0]//2+2, size[1]//2:size[1]//2+2] = 1
    return grid

def get_glider_config(size=(20, 20)):
    grid = np.zeros(size, dtype=int)
    grid[1, 2] = 1; grid[2, 3] = 1; grid[3, 1:4] = 1
    return grid

def get_r_pentomino_config(size=(20, 20)):
    grid = np.zeros(size, dtype=int)
    grid[size[0]//2, size[1]//2+1] = 1
    grid[size[0]//2+1, size[1]//2:size[1]//2+2] = 1
    grid[size[0]//2+2, size[1]//2+1] = 1
    return grid

np.random.seed(42)
configs = {
    'Block': get_block_config(),
    'Glider': get_glider_config(),
    'R-Pentomino': get_r_pentomino_config(),
    'Random': np.random.choice([0, 1], size=(20, 20), p=[0.5, 0.5])
}

for name, g in configs.items():
    cur = g.copy()
    e_vals, lz_vals = [], []
    for _ in range(80):
        e_vals.append(shannon_entropy(cur))
        lz_vals.append(lempel_ziv_complexity(''.join(map(str, cur.flatten()))))
        cur = gol_step(cur)
    print(f'{name:12s} | Entropy: min={min(e_vals):.3f}, max={max(e_vals):.3f}, mean={np.mean(e_vals):.3f} | LZ: min={min(lz_vals)}, max={max(lz_vals)}, mean={np.mean(lz_vals):.1f}')
""}

